//! Aspire -- the fold-backlog roadmap, drained verbatim from v2
//! `F:\\NewRepo\crates\forge-book\src\aspire.rs` (2026-08-13, 184 rows across
//! 14 lanes). NOW 475 rows across 40 lane glyphs, 72 landed -- counted
//! 2026-08-25, held by `aspire_carries_184_rows` and `exactly_ten_rows_landed`,
//! which are the numbers to trust when this line drifts again. Each row is an
//! `Aspirant`: a named capability not yet landed, carrying its `Reach` (the
//! lateral domain it was pulled from -- a paper, a discipline, a crate
//! already in-lock).
//!
//! ONE CHANGE from the v2 source: `landed` is now a real `bool` field, not a
//! trailing `// LANDED ...` Rust comment. v2 tracked landing status as prose
//! a human reads; this port makes it a value a program can read, because the
//! whole point of wiring this to the sky (`shell/src/mud.rs`) is that a
//! landed row must be able to change what pixels paint. The two extra
//! constructors below (`al`, `agl`) touch ONLY the 10 rows that were already
//! marked landed in the v2 source -- the other 174 rows are byte-identical to
//! their v2 originals.
//!
//! Two things intentionally NOT ported: `AtlasSection`/`Chapter` (used only
//! by v2's `aspire_chapter()`, which doesn't exist here -- this crate has no
//! book-chapter concept) and `latent_synthesis::SYNTHESES` (a 3-entry table
//! only ever read by the three `ᐯ` wormhole rows below -- inlined as literal
//! `Reach` values instead of porting a whole second module for three reads).

/// The lateral carrier -- the far domain a row was projected FROM, and what
/// the crossing costs and buys. A row without a `mechanism` is aimed, not
/// synthesised.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Reach {
    /// The orthogonal field reached into (paper, crate, discipline). "" = unrecorded.
    pub domain: &'static str,
    /// HOW -- algorithm or coordinates, never a metaphor. "" = unrecorded.
    pub mechanism: &'static str,
    /// WHAT -- the capability that exists only once it lands. "" = unrecorded.
    pub impact: &'static str,
}

/// Rows generated before the reach was carried in the type. Not a verdict:
/// the row stands, its crossing was simply never written down.
pub const UNSOURCED: Reach = Reach { domain: "", mechanism: "", impact: "" };

impl Reach {
    /// Aimed at a domain but with no body written.
    pub const fn aimed(domain: &'static str) -> Self {
        Reach { domain, mechanism: "", impact: "" }
    }

    /// Full crossing recorded: domain reached, mechanism stated, impact named.
    pub const fn is_sourced(&self) -> bool {
        !self.mechanism.is_empty() && !self.impact.is_empty() && !self.domain.is_empty()
    }
}

/// Triage tier -- what a row is waiting on. `'1'` wire-in-place (the parts
/// are already compiled) · `'2'` priced buy (an absent crate/paper) ·
/// `'3'` spec owed (no body yet). `'·'` = ungauged.
pub const UNGAUGED_TRIAGE: char = '\u{00B7}';

/// One look-ahead candidate: organ glyph, bucket, roi, skill, fold target,
/// reach, the two gauges every run must print (estimated LoC and triage
/// tier), and whether it has actually landed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Aspirant {
    /// Lane glyph -- which organ/run this row belongs to.
    pub glyph: &'static str,
    /// NOW / NEXT / LATER / HORIZON / EDGE.
    pub bucket: &'static str,
    /// ROI tier: H(igh) / M(edium) / L(ow) / E(dge).
    pub roi: char,
    /// Short skill/row identifier -- the star's name, effectively.
    pub skill: &'static str,
    /// What landing this row actually builds.
    pub target: &'static str,
    /// Where this row was pulled from.
    pub reach: Reach,
    /// Estimated lines to land the row. `0` = ungauged, never "free".
    pub loc: u32,
    /// Triage tier, see [`UNGAUGED_TRIAGE`].
    pub triage: char,
    /// Has this row actually landed? The one real addition over the v2
    /// source -- see the module doc.
    pub landed: bool,
}

impl Aspirant {
    /// A row carries its full gauge only with both an LoC estimate and a tier.
    pub const fn is_gauged(&self) -> bool {
        self.loc > 0 && self.triage != UNGAUGED_TRIAGE
    }
}

/// Row constructor -- not landed, ungauged. Matches v2's `a()` exactly.
const fn a(glyph: &'static str, bucket: &'static str, roi: char, skill: &'static str, target: &'static str, reach: Reach) -> Aspirant {
    Aspirant { glyph, bucket, roi, skill, target, reach, loc: 0, triage: UNGAUGED_TRIAGE, landed: false }
}

/// Landed variant of [`a`] -- same shape, `landed: true`. Used ONLY for the
/// rows the v2 source already marked `// LANDED ...`.
const fn al(glyph: &'static str, bucket: &'static str, roi: char, skill: &'static str, target: &'static str, reach: Reach) -> Aspirant {
    Aspirant { glyph, bucket, roi, skill, target, reach, loc: 0, triage: UNGAUGED_TRIAGE, landed: true }
}

/// Gauged row constructor -- not landed. Matches v2's `ag()` exactly.
#[allow(clippy::too_many_arguments)]
const fn ag(glyph: &'static str, bucket: &'static str, roi: char, loc: u32, triage: char, skill: &'static str, target: &'static str, reach: Reach) -> Aspirant {
    Aspirant { glyph, bucket, roi, skill, target, reach, loc, triage, landed: false }
}

/// Landed variant of [`ag`].
#[allow(clippy::too_many_arguments)]
const fn agl(glyph: &'static str, bucket: &'static str, roi: char, loc: u32, triage: char, skill: &'static str, target: &'static str, reach: Reach) -> Aspirant {
    Aspirant { glyph, bucket, roi, skill, target, reach, loc, triage, landed: true }
}

