#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn aspire_carries_184_rows() {
        assert_eq!(ASPIRE.len(), 509, "row-count pin. Every bump is a dated line in .forge/grind-log/aspire-pin-history.md (history moved out of source 2026-09-05, Sean: clip aspire).");
    }

    #[test]
    fn music_doa_steer_names_its_landed_verdict_half() {
        let row = ASPIRE.iter().find(|a| a.skill == "music-doa-steer").expect("music-doa-steer row");
        assert!(row.target.contains("nipr.rs"), "the steering row must point at its verdict half: {}", row.target);
        assert_eq!(row.reach.domain, "Schmidt 1986 MUSIC algorithm");
        assert!(!row.landed, "the steering half is still open");
    }

    #[test]
    fn exactly_ten_rows_landed() {
        let landed = ASPIRE.iter().filter(|a| a.landed).count();
        assert_eq!(
            landed, 154,
            "aspire landed-count drifted. Flip a row ONLY via `cargo xtask aspire mark-landed`, \
             then update this number and write the WHY to .forge/grind-log/. \
             Cross-check structurally: grep '^\\s*agl\\(' + '^\\s*al\\(' over this file. \
             (2026-08-26: 24 chained weld narratives were removed from this message — ~15KB of \
             prose inside a source file. They live in the grind-logs, dated and receipted.)"
        );
    }


    #[test]
    fn no_row_is_blank() {
        for a in ASPIRE {
            assert!(!a.glyph.is_empty(), "a row with no lane glyph");
            assert!(!a.skill.is_empty(), "a row with no skill name");
            assert!(!a.target.is_empty(), "a row with no target");
        }
    }

    #[test]
    fn landed_rows_are_the_named_ten() {
        let names: Vec<&str> = ASPIRE.iter().filter(|a| a.landed).map(|a| a.skill).collect();
        for expect in [
            "audio-engineer",
            "signal-condense",
            "stink-worker",
            "handoff",
            "machine-eyes-gate",
            "scrub-ghostmoon-read",
            "portrayal-slot-resolve",
            "emit-text-runs",
            "html5ever-parity-oracle",
            "scrub-harmonics-cue",
            "bformat-reinterpret",
            "colour-gradient-resolvent",
        ] {
            assert!(names.contains(&expect), "{expect} must be marked landed");
        }
    }

    /// `Reach::is_sourced` must actually discriminate: a row given a real
    /// domain+mechanism+impact reports sourced, `UNSOURCED` does not -- not every
    /// landed row is sourced (pre-Reach-tracking rows are allowed to stay
    /// `UNSOURCED` per the module doc), but the function's verdict must be real.
    #[test]
    fn is_sourced_discriminates_real_rows() {
        assert!(!UNSOURCED.is_sourced(), "UNSOURCED must never report sourced");
        let some_sourced = ASPIRE.iter().any(|a| a.reach.is_sourced());
        assert!(some_sourced, "at least one row in ASPIRE must carry a full Reach");
    }

    /// At least some rows must carry a real LoC estimate and triage tier, not
    /// the ungauged default. Wires `Aspirant::is_gauged`.
    #[test]
    fn some_rows_are_gauged() {
        let gauged = ASPIRE.iter().filter(|a| a.is_gauged()).count();
        assert!(gauged > 0, "no row in ASPIRE carries a real LoC+triage gauge");
    }
}
